CREATE TABLE IF NOT EXISTS foreground_time_coverage (
    id INTEGER PRIMARY KEY CHECK(id = 1), started_at TEXT NOT NULL
  )

CREATE TABLE IF NOT EXISTS node_version_local_origins (
    version_id TEXT PRIMARY KEY REFERENCES node_sync_versions(version_id) ON DELETE CASCADE
  )

CREATE TRIGGER IF NOT EXISTS trg_sync_delivery_device_leave
   AFTER UPDATE OF state ON sync_group_devices WHEN NEW.state = 'left' BEGIN
     DELETE FROM sync_delivery_receipts WHERE peer_id = NEW.device_identity_key;
     DELETE FROM sync_peer_cursors WHERE peer_id = NEW.device_identity_key;
   END

CREATE TRIGGER IF NOT EXISTS trg_sync_identity_nodes_insert
      AFTER INSERT ON nodes BEGIN INSERT INTO sync_identity_dirty_keys (object_type, object_id)
    SELECT 'node', NEW.id WHERE NOT EXISTS (
      SELECT 1 FROM sync_identity_dirty_keys
      WHERE object_type = 'node' AND object_id = NEW.id
    );
INSERT INTO sync_identity_dirty_keys (object_type, object_id)
    SELECT 'node_reading', NEW.id WHERE NOT EXISTS (
      SELECT 1 FROM sync_identity_dirty_keys
      WHERE object_type = 'node_reading' AND object_id = NEW.id
    );
INSERT INTO sync_identity_dirty_keys (object_type, object_id)
    SELECT 'node_review', NEW.id WHERE NOT EXISTS (
      SELECT 1 FROM sync_identity_dirty_keys
      WHERE object_type = 'node_review' AND object_id = NEW.id
    );
INSERT INTO sync_identity_dirty_keys (object_type, object_id)
    SELECT 'node_open_state', NEW.id WHERE NOT EXISTS (
      SELECT 1 FROM sync_identity_dirty_keys
      WHERE object_type = 'node_open_state' AND object_id = NEW.id
    ); END

